def authored_questions():
    out=[]
    for group,title,text,items in PASSAGES:
        for i,(prompt,options,answer,why,kind) in enumerate(items):
            # Rotate distractors deterministically so answer positions are balanced.
            if kind!='true-false-not-given':
                shift=i%len(options);options=options[shift:]+options[:shift];answer=(answer-shift)%len(options)
            out.append(dict(id=f'authored-{group}-{i+1}',skill='阅读',tag='tfng' if kind=='true-false-not-given' else 'detail',passage=text,q=prompt,options=options,answer=answer,why=why,quality='authored-unreviewed',difficulty='uncalibrated',sourceIds=['official-format'],origin='original-authored',groupId=group,topic=title,family=f'authored-{group}-{kind}',taskType=kind))
    return out
